// Generate light overrides from the existing neutral UI colors. Artwork and
// image overlays intentionally keep their original dark treatments.
const fs = require('fs');
const path = require('path');
const postcss = require('postcss');

const src = path.join(__dirname, '..', 'src');
const files = ['pages/store.css', 'pages/library.css', 'pages/community.css', 'pages/settings.css', 'pages/search.css', 'pages/details.css', 'pages/live-streams.css', 'pages/login.css', 'components/SideNav.css', 'components/notification.css', 'components/ErrorBoundary.css'];
const artwork = /(?:hero|featured|feature-card|feature-content|feature-shade|banner|artwork|game-art|card-art|wishlist|live-card|live-preview|live-player|logo|platform|avatar|poster-art|image|thumbnail|screenshot|gallery|shade|overlay)/i;
const colorPattern = /#[\da-f]{3,8}\b|\b(?:white|black)\b/gi;

function convert(value, property) {
  if (/gradient\(|url\(|var\(/i.test(value)) return value;
  return value.replace(colorPattern, (original) => {
    let hex = original.toLowerCase();
    if (hex === 'white') hex = '#ffffff';
    if (hex === 'black') hex = '#000000';
    if (hex.length === 4) hex = '#' + [...hex.slice(1)].map((c) => c + c).join('');
    if (hex.length !== 7) return original;
    const channels = [1, 3, 5].map((start) => parseInt(hex.slice(start, start + 2), 16));
    if (Math.max(...channels) - Math.min(...channels) > 8) return original;
    const level = channels[0];
    if (property.startsWith('background')) return level < 10 ? '#f7f7f7' : level < 30 ? '#ffffff' : level < 70 ? '#eeeeee' : level > 210 ? '#1b1b1b' : '#dedede';
    if (property.startsWith('border') || property.startsWith('outline')) return level < 80 ? '#d9d9d9' : level > 210 ? '#242424' : '#aaa';
    return level > 220 ? '#181818' : level > 175 ? '#414141' : level > 105 ? '#626262' : level < 40 ? '#ffffff' : '#777777';
  });
}

const output = postcss.root();
for (const file of files) {
  const tree = postcss.parse(fs.readFileSync(path.join(src, file), 'utf8'), { from: file });
  tree.walkAtRules((rule) => { if (!['media', 'container', 'supports'].includes(rule.name)) rule.remove(); });
  tree.walkRules((rule) => {
    const selectors = rule.selectors.filter((selector) => !artwork.test(selector) && !selector.includes(':root'));
    if (!selectors.length) { rule.remove(); return; }
    rule.selectors = selectors.map((selector) => `html[data-theme="light"] ${selector}`);
    rule.walkDecls((decl) => {
      if (!/^(color|background|background-color|border(?:-(?:color|top|bottom|left|right))?|outline|outline-color)$/.test(decl.prop)) { decl.remove(); return; }
      const next = convert(decl.value, decl.prop);
      if (next === decl.value) decl.remove(); else decl.value = next;
    });
    if (!rule.nodes.length) rule.remove();
  });
  tree.walkAtRules((rule) => { if (!rule.nodes?.length) rule.remove(); });
  output.append(...tree.nodes);
}
fs.writeFileSync(path.join(src, 'light-theme.generated.css'), '/* Generated by scripts/generate-light-theme.cjs. */\n' + output.toString() + '\n');
